import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const e = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(e); setResult(e);
    } catch { setError('Kunde inte analysera. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{setResult(null);setText('');}} setPage={setPage}/>;

  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, position:'relative', overflow:'hidden' }}>

      {/* Large orb — top centre, dominates */}
      <div style={{ position:'absolute', top:'-8%', left:'50%', transform:'translateX(-50%)', zIndex:0, animation:'fadeIn 1.2s ease both', opacity:0.95 }}>
        <MeshSphere size={420} speed={0.35} distort={0.4} hue1={195} hue2={215} />
      </div>

      {/* Top metadata */}
      <div style={{ position:'relative', zIndex:2, padding:'28px 24px 0', display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
        <div>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.3)', marginBottom:2 }}>Spiral</p>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', color:'rgba(240,235,227,0.18)', textTransform:'uppercase' }}>KBT · AI</p>
        </div>
        {streak > 0 && (
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(240,235,227,0.4)', letterSpacing:'0.08em' }}>
            🔥 {streak} dagar
          </div>
        )}
      </div>

      {/* Big heading — sits OVER the orb like "glass." reference */}
      <div style={{ position:'relative', zIndex:2, padding:'0 20px', marginTop:'44vw', animation:'fadeUp .9s .3s both' }}>
        <h1 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(38px,10vw,64px)', fontWeight:400, fontStyle:'italic', lineHeight:1.1, color:'rgba(240,235,227,0.92)', marginBottom:6, letterSpacing:'-0.01em' }}>
          Vad snurrar<br/>i huvudet?
        </h1>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', color:'rgba(240,235,227,0.28)', textTransform:'uppercase', marginBottom:24 }}>
          KBT-baserad tankeanalys · AI
        </p>

        {/* Input */}
        <div style={{ background:'rgba(255,255,255,0.05)', border:'1px solid rgba(255,255,255,0.09)', borderRadius:20, overflow:'hidden', marginBottom:10, backdropFilter:'blur(12px)' }}>
          <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
            placeholder="Skriv fritt..."
            style={{ width:'100%', minHeight:100, background:'transparent', border:'none', color:'rgba(240,235,227,0.85)', fontSize:15, fontWeight:300, lineHeight:1.78, resize:'none', outline:'none', padding:'16px 18px' }} />
          <div style={{ padding:'10px 18px 14px', display:'flex', justifyContent:'space-between', alignItems:'center', borderTop:'1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,235,227,0.2)' }}>{text.length}/1000</span>
            <button onClick={submit} disabled={!text.trim()||loading}
              style={{ padding:'9px 22px', borderRadius:100, background: text.trim()&&!loading ? 'rgba(240,235,227,0.92)' : 'rgba(255,255,255,0.08)', color: text.trim()&&!loading ? '#120e0a' : 'rgba(240,235,227,0.25)', fontSize:12, fontWeight:700, border:'none', transition:'all .25s', boxShadow: text.trim()&&!loading ? '0 0 24px rgba(200,190,170,0.2)' : 'none' }}>
              {loading ? <span style={{ display:'flex',alignItems:'center',gap:7 }}><span style={{ width:10,height:10,border:'2px solid rgba(18,14,10,0.3)',borderTopColor:'#120e0a',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar</span> : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ padding:'0 18px 12px', fontSize:12, color:'rgba(220,120,100,0.8)' }}>{error}</p>}
        </div>

        {/* Quick links */}
        <div style={{ display:'flex', gap:8 }}>
          {[{id:'checkin',label:'Check-in'},{id:'breathing',label:'Andning'}].map(({id,label})=>(
            <button key={id} onClick={()=>setPage(id)}
              style={{ flex:1, padding:'12px', background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, color:'rgba(240,235,227,0.45)', fontSize:13, fontWeight:400, transition:'all .2s' }}
              onMouseEnter={e=>{e.currentTarget.style.background='rgba(255,255,255,0.08)';e.currentTarget.style.color='rgba(240,235,227,0.8)'}}
              onMouseLeave={e=>{e.currentTarget.style.background='rgba(255,255,255,0.04)';e.currentTarget.style.color='rgba(240,235,227,0.45)'}}>
              {label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, overflow:'hidden', position:'relative' }}>
      {/* Warm orb for analysis */}
      <div style={{ position:'absolute', top:'-12%', left:'50%', transform:'translateX(-50%)', zIndex:0, opacity:0.8 }}>
        <MeshSphere size={380} speed={0.28} distort={0.55} hue1={20} hue2={340} />
      </div>

      <div style={{ position:'relative', zIndex:2, padding:'28px 22px 0', animation:'fadeUp .7s both' }}>
        <div style={{ marginTop:'36vw' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.3)', marginBottom:4 }}>{result.trap_icon} Tankefälla</p>
          <h2 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(28px,8vw,46px)', fontWeight:400, fontStyle:'italic', lineHeight:1.1, color:'rgba(240,235,227,0.92)', marginBottom:20 }}>
            {result.trap_label}
          </h2>

          <p style={{ fontSize:12, color:'rgba(240,235,227,0.32)', fontStyle:'italic', lineHeight:1.7, marginBottom:20, paddingLeft:14, borderLeft:'1px solid rgba(255,255,255,0.12)' }}>
            "{text.slice(0,110)}{text.length>110?'...':''}"
          </p>

          {[
            { label:'Vad händer',  body:result.description },
            { label:'Omramning',   body:result.reframe },
            { label:'Övning',      body:result.exercise_text },
          ].map(({label,body})=>(
            <div key={label} style={{ marginBottom:12, background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:16, padding:'14px 16px', backdropFilter:'blur(10px)' }}>
              <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(240,235,227,0.3)', marginBottom:8 }}>{label}</p>
              <p style={{ fontSize:14, color:'rgba(240,235,227,0.72)', lineHeight:1.82, fontWeight:300 }}>{body}</p>
            </div>
          ))}

          <div style={{ display:'flex', gap:8, marginTop:8 }}>
            <button onClick={()=>setPage('breathing')} style={{ flex:1, padding:'13px', background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', borderRadius:14, color:'rgba(240,235,227,0.5)', fontSize:13 }}>🫁 Andning</button>
            <button onClick={onBack} style={{ padding:'13px 18px', fontSize:13, color:'rgba(240,235,227,0.28)' }}>← Tillbaka</button>
          </div>
        </div>
      </div>
    </div>
  );
}
